package ui

import (
	"encoding/base64"

	"fyne.io/fyne/v2"
)

// appLogoPng 应用Logo(PNG, 内嵌资源)
var appLogoPng = fyne.NewStaticResource("app_logo.png", decodeLogo())

// AppLogo 供应用入口设置窗口图标
func AppLogo() fyne.Resource {
	return appLogoPng
}

func decodeLogo() []byte {
	b, err := base64.StdEncoding.DecodeString(logoB64)
	if err != nil {
		return nil
	}
	return b
}

const logoB64 = ``
